statement-execution-processor.statement:
declare
    v_count INTEGER;
begin
    select count(1)
            into v_count
            from [PREFIX]_TABLES
           where OWNER = REPLACE({#0}, '"')
             and TABLE_NAME = 'CREATE$JAVA$LOB$TABLE';

    if v_count = 0 THEN
        execute immediate 'create table {0}."CREATE$JAVA$LOB$TABLE" (
                    "NAME" VARCHAR2(700) PRIMARY KEY,
                    "LOB" BLOB,
                    "LOADTIME" DATE)';
    end if;
end;

declare
    v_count INTEGER;
begin
    select count(1)
            into v_count
            from USER_TABLES
           where USER = REPLACE({#0}, '"')
             and TABLE_NAME = 'CREATE$JAVA$LOB$TABLE';

    if v_count = 0 THEN
        execute immediate 'create table {0}."CREATE$JAVA$LOB$TABLE" (
                    "NAME" VARCHAR2(700) PRIMARY KEY,
                    "LOB" BLOB,
                    "LOADTIME" DATE)';
    end if;
end;

declare
    v_content BLOB := {#2};
    v_content_id VARCHAR2(128) := SYS_GUID();
begin
    insert into {0}."CREATE$JAVA$LOB$TABLE" ("NAME", "LOB", "LOADTIME") VALUES (v_content_id, v_content, SYSDATE);

    if v_content is null then
        execute immediate 'create or replace java resource named {0}.{1} using blob (select EMPTY_BLOB() from DUAL)';
    else
        execute immediate 'create or replace java resource named {0}.{1} using blob "LOB" from {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    end if;
    delete {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = v_content_id;
exception
    when others then
        delete {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = v_content_id;
    raise;
end;

declare
    v_content BLOB := {#2};
    v_content_id VARCHAR2(128) := SYS_GUID();
begin
    insert into {0}."CREATE$JAVA$LOB$TABLE" ("NAME", "LOB", "LOADTIME") VALUES (v_content_id, v_content, SYSDATE);
    execute immediate 'create java class schema {0} using blob select "LOB" from {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    delete {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = v_content_id;
exception
    when others then
        delete {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = v_content_id;
    raise;
end;

declare
    v_content BLOB := {#2};
