begin
    insert into {0}."CREATE$JAVA$LOB$TABLE" ("NAME", "LOB", "LOADTIME") VALUES (v_content_id, v_content, SYSDATE);
    execute immediate 'create java source named {0}.{1} using blob select "LOB" from {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = '''||v_content_id||'''';
    delete {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = v_content_id;
exception
    when others then
        delete {0}."CREATE$JAVA$LOB$TABLE" where "NAME" = v_content_id;
