begin
    begin
        execute immediate 'drop java source {0}.{1}';
    exception
        when others then
            if SQLCODE != -4043 then raise; end if;
    end;

    begin
        execute immediate 'drop java class {0}.{1}';
    exception
        when others then
            if SQLCODE != -4043 then raise; end if;
    end;
end;

begin
    dbms_java.set_compiler_option({#0}, {#1}, {#2});
end;

declare
    result varchar2(4000);
begin
    result := dbms_java.set_property({#0}, {#1});
end;

begin
    execute immediate 'alter JAVA SOURCE {0}.{1} compile';
exception
when others then
    execute immediate 'alter JAVA CLASS {0}.{1} compile';
end;
